            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE FIRST LINE</text><text x=\"550\" y=\"120\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">Four words that frame 1,168 pages</text><rect x=\"150\" y=\"250\" width=\"800\" height=\"220\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"375\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"48\">Who is John Galt?</text><text x=\"900\" y=\"440\" text-anchor=\"end\" fill=\"#8b5cf6\" font-size=\"18\">-- Atlas Shrugged, Part One</text><rect x=\"150\" y=\"580\" width=\"800\" height=\"150\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"640\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">Part One: a shrug of despair</text><text x=\"550\" y=\"685\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Later: a question with a real answer</text></svg>",
