            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"160\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(245,158,11,0.1)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"550\" y=\"225\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"24\">DAGNY FLAW</text><text x=\"550\" y=\"275\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Even Rand heroine makes a mistake</text><text x=\"550\" y=\"310\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">Hint: think about the title of the novel</text><rect x=\"300\" y=\"430\" width=\"500\" height=\"110\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"495\" text-anchor=\"middle\" fill=\"#6366f1\" font-size=\"24\">Carrying the world alone</text></svg>",
