            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">FINAL CHECK</text><rect x=\"150\" y=\"150\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"215\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">REARDEN FLAW</text><text x=\"550\" y=\"265\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Not practical -- moral</text><text x=\"550\" y=\"305\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">What does he wrongly accept?</text><rect x=\"200\" y=\"450\" width=\"700\" height=\"80\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"500\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">Hint: think of the trial and the family</text></svg>",
