            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"120\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"180\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">THE VALLEY CODE</text><text x=\"550\" y=\"225\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">How do residents deal with each other?</text><text x=\"550\" y=\"260\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Think about Dagny and her wages</text><circle cx=\"360\" cy=\"520\" r=\"110\" fill=\"rgba(16,185,129,0.15)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"360\" y=\"528\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">TRADE?</text><circle cx=\"740\" cy=\"520\" r=\"110\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"740\" y=\"528\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"24\">SHARE?</text></svg>",
            "caption": "Recall the one forbidden word."
