            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE LAST LINES</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">An ending that is a beginning</text><rect x=\"150\" y=\"200\" width=\"800\" height=\"220\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"290\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"30\">The road is cleared.</text><text x=\"550\" y=\"350\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"30\">We are going back to the world.</text><rect x=\"60\" y=\"500\" width=\"460\" height=\"220\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"290\" y=\"560\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"22\">WHAT ENDS</text><text x=\"290\" y=\"610\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">the looters world</text><text x=\"290\" y=\"645\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">of pull and need</text><rect x=\"580\" y=\"500\" width=\"460\" height=\"220\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"810\" y=\"560\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"22\">WHAT BEGINS</text><text x=\"810\" y=\"610\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">a rebuilt society</text><text x=\"810\" y=\"645\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">on the strikers terms</text></svg>",
